#[test]
fn publishes_once() {
    struct Shunt { seen: RefCell<Vec<String>> }      // test-local collaborator
    impl Listener for Shunt {
        fn on_event(&self, e: &str) { self.seen.borrow_mut().push(e.into()); }
    }
    let s = Shunt { seen: RefCell::new(vec![]) };
    Publisher::new(&s).change("x");                  // install the shunt
    assert_eq!(*s.seen.borrow(), ["x"]);
}
